import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeVacationStatus = () => {
    const [requests, setRequests] = useState([]);
    const [newNotifications, setNewNotifications] = useState(0);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();
    const user = JSON.parse(localStorage.getItem('user'));

    useEffect(() => {
        if (user) {
            fetchVacationRequests();
        }
    }, [user]);

    const fetchVacationRequests = async () => {
        try {
            setLoading(true);
            setError(null);

            const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-requests`, {
                headers: {
                    'Authorization': `Bearer ${localStorage.getItem('token') || ''}`
                }
            });

            if (!response.ok) {
                throw new Error(`Error ${response.status}: ${response.statusText}`);
            }

            const data = await response.json();

            // Agrupar por request_group_id con manejo de casos null
            const grouped = data.reduce((acc, req) => {
                const groupId = req.request_group_id || `individual_${req.id}`;
                if (!acc[groupId]) {
                    acc[groupId] = {
                        id: groupId,
                        dates: [],
                        status: req.status,
                        comments: req.comments,
                        notification_read: req.notification_read,
                        created_at: req.created_at || new Date().toISOString()
                    };
                }
                acc[groupId].dates.push(req.vacation_date);
                return acc;
            }, {});

            // Ordenar por fecha más reciente primero
            const sortedRequests = Object.values(grouped).sort((a, b) =>
                new Date(b.created_at) - new Date(a.created_at)
            );

            setRequests(sortedRequests);
            updateNotificationCount(sortedRequests);
        } catch (err) {
            console.error('Error fetching vacation requests:', err);
            setError(err.message);

            // Reintentar después de 5 segundos si es error de recursos
            if (err.message.includes('Failed to fetch') || err.message.includes('ERR_INSUFFICIENT_RESOURCES')) {
                setTimeout(() => {
                    fetchVacationRequests();
                }, 5000);
            }
        } finally {
            setLoading(false);
        }
    };

    const updateNotificationCount = (requestsData) => {
        const unread = requestsData.filter(req =>
            req.status !== 'pending' && !req.notification_read
        ).length;
        setNewNotifications(unread);
    };

    const markAsRead = async (requestId) => {
        try {
            await fetch(`${API_BASE_URL}/users/mark-notification-read/${requestId}`, {
                method: 'PUT',
                headers: {
                    'Authorization': `Bearer ${localStorage.getItem('token') || ''}`
                }
            });

            // Actualización optimista
            const updatedRequests = requests.map(req =>
                req.id === requestId ? {...req, notification_read: true} : req
            );
            setRequests(updatedRequests);
            updateNotificationCount(updatedRequests);
        } catch (error) {
            console.error('Error marking notification as read:', error);
        }
    };

    return (
        <div className="min-h-screen bg-gray-100 p-6">
            <div className="flex items-center gap-4 mb-6">
                <button
                    onClick={() => navigate('/employee')}
                    className="w-10 h-10 rounded-lg bg-red-600 text-white shadow hover:bg-red-700 transition flex-shrink-0 flex items-center justify-center"
                >
                    <ArrowLeft className="w-5 h-5" />
                </button>
                <h1 className="text-3xl font-bold text-gray-800">Estado de Solicitudes de Vacaciones</h1>
            </div>

            {error && (
                <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6">
                    <div className="flex">
                        <div className="flex-shrink-0">
                            <svg className="h-5 w-5 text-red-500" fill="currentColor" viewBox="0 0 20 20">
                                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                            </svg>
                        </div>
                        <div className="ml-3">
                            <h3 className="text-sm font-medium text-red-800">Error al cargar solicitudes</h3>
                            <div className="mt-2 text-sm text-red-700">
                                <p>{error}</p>
                                <button
                                    onClick={fetchVacationRequests}
                                    className="mt-2 inline-flex items-center px-3 py-1 border border-transparent text-sm font-medium rounded-md text-red-700 bg-red-100 hover:bg-red-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
                                >
                                    Reintentar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <div className="bg-white shadow-lg rounded-lg overflow-hidden">
                <div className="bg-red-600 p-4">
                    <div className="flex justify-between items-center">
                        <h2 className="text-xl font-semibold text-white">Tus Solicitudes</h2>
                        {newNotifications > 0 && (
                            <span className="bg-white text-red-600 rounded-full px-3 py-1 text-sm font-medium">
                                {newNotifications} nueva(s)
                            </span>
                        )}
                    </div>
                </div>

                {loading ? (
                    <div className="p-8 text-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-red-600 mx-auto"></div>
                        <p className="mt-4 text-gray-600">Cargando solicitudes...</p>
                    </div>
                ) : requests.length === 0 ? (
                    <div className="p-8 text-center">
                        <p className="text-gray-600">No tienes solicitudes de vacaciones registradas.</p>
                        <button
                            onClick={fetchVacationRequests}
                            className="mt-4 inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
                        >
                            Refrescar
                        </button>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-red-50">
                            <tr>
                                <th className="p-3 text-left text-red-600">Período</th>
                                <th className="p-3 text-left text-red-600">Estado</th>
                                <th className="p-3 text-left text-red-600">Comentarios</th>
                                <th className="p-3 text-left text-red-600">Notificación</th>
                            </tr>
                            </thead>
                            <tbody>
                            {requests.map((group) => {
                                const sortedDates = [...group.dates].sort();
                                const from = sortedDates[0];
                                const to = sortedDates[sortedDates.length - 1];
                                const dateRange = from === to ? from : `${from} al ${to}`;

                                return (
                                    <tr
                                        key={group.id}
                                        className={`border-b ${
                                            !group.notification_read && group.status !== 'pending'
                                                ? 'bg-blue-50 hover:bg-blue-100 cursor-pointer'
                                                : 'hover:bg-gray-50'
                                        }`}
                                        onClick={() => !group.notification_read && group.status !== 'pending' && markAsRead(group.id)}
                                    >
                                        <td className="p-3 font-medium">{dateRange}</td>
                                        <td className="p-3">
                                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                                                    group.status === 'approved' ? 'bg-green-100 text-green-800' :
                                                        group.status === 'rejected' ? 'bg-red-100 text-red-800' :
                                                            'bg-yellow-100 text-yellow-800'
                                                }`}>
                                                    {group.status === 'approved' ? 'Aprobado' :
                                                        group.status === 'rejected' ? 'Rechazado' : 'Pendiente'}
                                                </span>
                                        </td>
                                        <td className="p-3 text-sm text-gray-600">
                                            {group.comments || 'Sin comentarios'}
                                        </td>
                                        <td className="p-3">
                                                <span className={`text-xs font-medium ${
                                                    group.notification_read ? 'text-gray-500' : 'text-blue-600'
                                                }`}>
                                                    {group.notification_read ? 'Leído' : 'Nuevo'}
                                                </span>
                                        </td>
                                    </tr>
                                );
                            })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default EmployeeVacationStatus;
